1	use std::env;
2	use std::ffi::{OsStr, OsString};
3	use std::fs;
4	use std::io::Read;
5	use std::path::Path;
6	use std::process::ExitCode;
7	
8	use roottrace::{hex, hex_nibble, is_lower_hex, proof_json, root_and_path, split_records, RootStream};
9	
10	const VERSION: &str = "0.1.0";
11	
12	const USAGE: &str = "\
13	Usage:
14	    roottrace root <file>
15	    roottrace prove <file> <record-index>
16	    roottrace verify <record-file> <proof-file> <trusted-tree-size> <trusted-root>
17	    roottrace --version
18	
19	Commands:
20	    root <file>
21	        Print the SHA-256 RFC 6962 Merkle Tree Hash of all records in <file>
22	        as one line of 64 lowercase hexadecimal characters.
23	
24	    prove <file> <record-index>
25	        Print the RFC 6962 section 2.1.1 inclusion (membership) proof for the
26	        record at <record-index> within the whole batch. The index is
27	        0-based and counts records in file order: 0 is the first record,
28	        1 the second, and so on; the same content at multiple positions gets
29	        the proof for the exact position given, with no deduplication. Output
30	        is one JSON object with the fields tree_size, leaf_index, root and
31	        audit_path (leaf-to-root hashes, lowercase hex; empty for a batch of
32	        exactly one record).
33	
34	        Example:
35	            roottrace prove batch.txt 0
36	
37	    verify <record-file> <proof-file> <trusted-tree-size> <trusted-root>
38	        Verify an inclusion proof produced by `prove` without needing the
39	        whole batch. The record file holds the raw bytes of exactly one
40	        target record (no LF splitting, byte for byte including any trailing
41	        LF/space/CR, NUL and non-UTF-8 bytes; an empty file is one empty
42	        record). The proof is read as one complete JSON object. The trusted
43	        tree size (an ASCII decimal positive integer) and the trusted root
44	        (64 lowercase hexadecimal characters) must be confirmed
45	        independently; they are never taken from fields inside the proof.
46	        On success stdout is exactly \"verified\\n\", stderr is empty and the
47	        exit status is 0.
48	
49	        Example:
50	            roottrace verify record.bin proof.json 9 a8a3e76e...723adc3
51	
52	Exit status:
53	    0  success
54	    1  an input file cannot be read, the proof is malformed, or verification fails
55	    2  usage error (unknown command, missing or extra arguments, bad arguments)";
56	
57	fn main() -> ExitCode {
58	    // Raw OS arguments: file paths are handed to the filesystem exactly as
59	    // received, byte for byte. On Unix a path may contain bytes that are not
60	    // valid UTF-8 (e.g. 0xff); such a path is not invalid and must reach the
61	    // file rather than aborting argument collection. The command name, the
62	    // record index and the trusted tree size/root arguments are required to
63	    // be UTF-8 text.
64	    let args: Vec<OsString> = env::args_os().skip(1).collect();
65	    match args.as_slice() {
66	        [flag] if flag == OsStr::new("--version") => {
67	            println!("roottrace {VERSION}");
68	            ExitCode::SUCCESS
69	        }
70	        [cmd, path] if cmd == OsStr::new("root") => match merkle_root_of_file(Path::new(path)) {
71	            Ok(root) => {
72	                println!("{}", hex(&root));
73	                ExitCode::SUCCESS
74	            }
75	            Err(reason) => {
76	                eprintln!("roottrace: {reason}");
77	                ExitCode::FAILURE
78	            }
79	        },
80	        [cmd, path, index] if cmd == OsStr::new("prove") => match parse_index(index) {
81	            Some(index) => match proof_for_file(Path::new(path), index) {
82	                Ok(proof) => {
83	                    println!("{}", proof);
84	                    ExitCode::SUCCESS
85	                }
86	                Err(ProveError::Read(reason)) => {
87	                    eprintln!("roottrace: {reason}");
88	                    ExitCode::FAILURE
89	                }
90	                Err(ProveError::Missing(index, size)) => {
91	                    if size == 0 {
92	                        eprintln!(
93	                            "roottrace: record index {index} does not exist: the file holds zero records"
94	                        );
95	                    } else {
96	                        eprintln!(
97	                            "roottrace: record index {index} does not exist: file holds {size} record(s), valid indices are 0 through {}",
98	                            size - 1
99	                        );
100	                    }
101	                    ExitCode::FAILURE
102	                }
103	            },
104	            None => {
105	                let shown = index.to_string_lossy();
106	                eprintln!("roottrace: invalid record index '{shown}': expected a decimal non-negative integer of ASCII digits");
107	                eprintln!("{USAGE}");
108	                ExitCode::from(2)
109	            }
110	        },
111	        [cmd, path, proof_path, size_arg, root_arg] if cmd == OsStr::new("verify") => {
112	            match (parse_trusted_size(size_arg), parse_trusted_root(root_arg)) {
113	                (Some(trusted_size), Some(trusted_root)) => {
114	                    match verify_files(Path::new(path), Path::new(proof_path), trusted_size, &trusted_root) {
115	                        Ok(()) => {
116	                            println!("verified");
117	                            ExitCode::SUCCESS
118	                        }
119	                        Err(VerifyError::Read { path, source }) => {
120	                            eprintln!(
121	                                "roottrace: cannot read '{}': {source}",
122	                                display_path(&path)
123	                            );
124	                            ExitCode::FAILURE
125	                        }
126	                        Err(VerifyError::MalformedProof(reason)) => {
127	                            eprintln!("roottrace: invalid proof: {reason}");
128	                            ExitCode::FAILURE
129	                        }
130	                        Err(VerifyError::Failed(reason)) => {
131	                            eprintln!("roottrace: verification failed: {reason}");
132	                            ExitCode::FAILURE
133	                        }
134	                    }
135	                }
136	                (bad_size, bad_root) => {
137	                    if bad_size.is_none() {
138	                        let shown = size_arg.to_string_lossy();
139	                        eprintln!(
140	                            "roottrace: invalid trusted tree size '{shown}': expected an ASCII decimal positive integer within unsigned 64-bit range"
141	                        );
142	                    }
143	                    if bad_root.is_none() {
144	                        let shown = root_arg.to_string_lossy();
145	                        eprintln!(
146	                            "roottrace: invalid trusted root '{shown}': expected exactly 64 lowercase hexadecimal characters"
147	                        );
148	                    }
149	                    eprintln!("{USAGE}");
150	                    ExitCode::from(2)
151	                }
152	            }
153	        }
154	        _ => {
155	            eprintln!("{USAGE}");
156	            ExitCode::from(2)
157	        }
158	    }
159	}
160	
161	enum ProveError {
162	    Read(String),
163	    Missing(u64, u64),
164	}
165	
166	/// Failures reported by `verify`, kept separate so that malformed proofs and
167	/// cryptographic mismatches both exit 1 but say different things on stderr.
168	enum VerifyError {
169	    /// One of the two input paths cannot be read (missing, a directory, ...).
170	    Read { path: std::path::PathBuf, source: std::io::Error },
171	    /// The proof bytes are not a well-formed proof object.
172	    MalformedProof(String),
173	    /// The proof is well-formed but does not establish the claimed inclusion
174	    /// against the independently trusted tree size and root.
175	    Failed(String),
176	}
177	
178	/// Read the two input files and run an RFC 6962 inclusion check. The record
179	/// file's ENTIRE byte content is the target record: no LF splitting and no
180	/// trimming of trailing LF, space or CR; NUL and non-UTF-8 bytes take part as
181	/// they are. A zero-byte file is one empty record. The check itself is the
182	/// library entry point `roottrace::verify_membership`, so the command and
183	/// Rust callers of the library share exactly one verification path.
184	fn verify_files(
185	    record_path: &Path,
186	    proof_path: &Path,
187	    trusted_size: u64,
188	    trusted_root: &[u8; 32],
189	) -> Result<(), VerifyError> {
190	    let record = fs::read(record_path).map_err(|source| VerifyError::Read {
191	        path: record_path.to_path_buf(),
192	        source,
193	    })?;
194	    let proof_bytes = fs::read(proof_path).map_err(|source| VerifyError::Read {
195	        path: proof_path.to_path_buf(),
196	        source,
197	    })?;
198	    match roottrace::verify_membership(&record, &proof_bytes, trusted_size, trusted_root) {
199	        Ok(_) => Ok(()),
200	        Err(roottrace::VerifyError::MalformedProof(reason)) => {
201	            Err(VerifyError::MalformedProof(reason))
202	        }
203	        Err(roottrace::VerifyError::VerificationFailed(reason)) => Err(VerifyError::Failed(reason)),
204	        // parse_trusted_size rejects zero before this function is ever
205	        // called, so the library's invalid-argument case cannot occur here.
206	        Err(roottrace::VerifyError::InvalidTrustedSize) => {
207	            unreachable!("the command line only accepts a positive trusted tree size")
208	        }
209	    }
210	}
211	
212	/// Parse the trusted tree size given on the command line: one or more ASCII
213	/// decimal digits naming a POSITIVE 64-bit unsigned integer. Unlike a record
214	/// index, zero is not accepted (it cannot be a tree that contains a record).
215	/// Anything else (sign, whitespace, non-UTF-8 bytes, a value above u64::MAX)
216	/// is a usage error.
217	fn parse_trusted_size(arg: &OsStr) -> Option<u64> {
218	    let text = arg.to_str()?;
219	    if text.is_empty() || !text.bytes().all(|b| b.is_ascii_digit()) {
220	        return None;
221	    }
222	    let mut value: u64 = 0;
223	    for b in text.bytes() {
224	        value = value.checked_mul(10)?.checked_add(u64::from(b - b'0'))?;
225	    }
226	    if value == 0 {
227	        return None;
228	    }
229	    Some(value)
230	}
231	
232	/// Parse the trusted root given on the command line: exactly 64 lowercase
233	/// ASCII hexadecimal characters (32 bytes). Uppercase, wrong length, non-hex
234	/// or non-UTF-8 bytes are usage errors.
235	fn parse_trusted_root(arg: &OsStr) -> Option<[u8; 32]> {
236	    let text = arg.to_str()?;
237	    if text.len() != 64 || !text.bytes().all(is_lower_hex) {
238	        return None;
239	    }
240	    let bytes = text.as_bytes();
241	    let mut out = [0u8; 32];
242	    for (i, pair) in bytes.chunks_exact(2).enumerate() {
243	        out[i] = (hex_nibble(pair[0])? << 4) | hex_nibble(pair[1])?;
244	    }
245	    Some(out)
246	}
247	
248	/// Render a path for a human-readable error message. This is used ONLY in
249	/// diagnostics: the filesystem is always given the raw `Path`, never this
250	/// lossy rendering, so a file whose name contains 0xff is not confused with a
251	/// differently named file that merely displays the same way.
252	fn display_path(path: &Path) -> String {
253	    path.to_string_lossy().into_owned()
254	}
255	
256	/// Compute the batch root by streaming the file through a fixed-size buffer.
257	/// The whole file is never held in memory: each record is hashed as its bytes
258	/// arrive (a record of any length is never stored), and the only state kept
259	/// across records is `RootStream`'s subtree stack of at most 64 hashes —
260	/// O(log n) in the record count, independent of the file's byte size and of
261	/// the longest record. The root printed for a batch is exactly the one the
262	/// previous whole-file implementation computed (and the one `prove` still
263	/// commits to), because `RootStream` folds the same RFC 6962 tree as `mth`.
264	fn merkle_root_of_file(path: &Path) -> Result<[u8; 32], String> {
265	    let mut file = fs::File::open(path)
266	        .map_err(|e| format!("cannot read '{}': {e}", display_path(path)))?;
267	    // Fixed read buffer: how many bytes one read returns cannot affect the
268	    // result — read boundaries are never record boundaries.
269	    let mut buf = [0u8; 64 * 1024];
270	    let mut stream = RootStream::new();
271	    loop {
272	        match file.read(&mut buf) {
273	            Ok(0) => break,
274	            Ok(n) => stream.feed(&buf[..n]),
275	            Err(e) if e.kind() == std::io::ErrorKind::Interrupted => continue,
276	            // A failure partway through (including a directory path, whose
277	            // open succeeds but whose read fails) aborts the whole command:
278	            // the partial batch read so far is never reported as a root.
279	            Err(e) => return Err(format!("cannot read '{}': {e}", display_path(path))),
280	        }
281	    }
282	    Ok(stream.finish())
283	}
284	
285	fn proof_for_file(path: &Path, index: u64) -> Result<String, ProveError> {
286	    let data = fs::read(path)
287	        .map_err(|e| ProveError::Read(format!("cannot read '{}': {e}", display_path(path))))?;
288	    let records = split_records(&data);
289	    let size = records.len() as u64;
290	    if index >= size {
291	        return Err(ProveError::Missing(index, size));
292	    }
293	    let idx = index as usize;
294	    let (root, audit_path) = root_and_path(&records, idx);
295	    Ok(proof_json(size, index, &root, &audit_path))
296	}
297	
298	/// Parse a record index: one or more ASCII decimal digits, non-negative, no
299	/// sign or whitespace, fitting in an unsigned 64-bit integer. Anything else
300	/// (including "+1", " 1", "1.0", "", "-1", or an argument that is not valid
301	/// UTF-8) is rejected as a usage error.
302	fn parse_index(arg: &OsStr) -> Option<u64> {
303	    let text = arg.to_str()?;
304	    if text.is_empty() || !text.bytes().all(|b| b.is_ascii_digit()) {
305	        return None;
306	    }
307	    let mut value: u64 = 0;
308	    for b in text.bytes() {
309	        value = value.checked_mul(10)?.checked_add(u64::from(b - b'0'))?;
310	    }
311	    Some(value)
312	}
313	
314	#[cfg(test)]
315	mod tests {
316	    use super::*;
317	    use std::os::unix::ffi::OsStrExt;
318	
319	    #[test]
320	    fn index_parsing_accepts_only_ascii_unsigned_decimal() {
321	        assert_eq!(parse_index(OsStr::new("0")), Some(0));
322	        assert_eq!(parse_index(OsStr::new("00")), Some(0));
323	        assert_eq!(parse_index(OsStr::new("123")), Some(123));
324	        assert_eq!(parse_index(OsStr::new("18446744073709551615")), Some(u64::MAX));
325	        assert_eq!(parse_index(OsStr::new("18446744073709551616")), None);
326	        assert_eq!(parse_index(OsStr::new("")), None);
327	        assert_eq!(parse_index(OsStr::new("-1")), None);
328	        assert_eq!(parse_index(OsStr::new("+1")), None);
329	        assert_eq!(parse_index(OsStr::new("1.0")), None);
330	        assert_eq!(parse_index(OsStr::new(" 1")), None);
331	        assert_eq!(parse_index(OsStr::new("1 ")), None);
332	        assert_eq!(parse_index(OsStr::new("0x1")), None);
333	        assert_eq!(parse_index(OsStr::new("①")), None);
334	        // Leading-zero overflow is still overflow.
335	        assert_eq!(parse_index(OsStr::new("0018446744073709551616")), None);
336	        // An argument that is not valid UTF-8 is a usage error, never a panic.
337	        assert_eq!(parse_index(OsStr::from_bytes(b"1\xff")), None);
338	        assert_eq!(parse_index(OsStr::from_bytes(b"\xff")), None);
339	    }
340	
341	    // --- trusted command-line arguments -------------------------------------
342	
343	    #[test]
344	    fn trusted_size_accepts_only_positive_ascii_decimal_u64() {
345	        assert_eq!(parse_trusted_size(OsStr::new("1")), Some(1));
346	        assert_eq!(parse_trusted_size(OsStr::new("09")), Some(9));
347	        assert_eq!(parse_trusted_size(OsStr::new("18446744073709551615")), Some(u64::MAX));
348	        // Zero is not a tree that can contain a record.
349	        assert_eq!(parse_trusted_size(OsStr::new("0")), None);
350	        assert_eq!(parse_trusted_size(OsStr::new("00")), None);
351	        for bad in ["", "-1", "+1", "1.0", " 1", "1 ", "0x1", "18446744073709551616", "①"] {
352	            assert_eq!(parse_trusted_size(OsStr::new(bad)), None, "size {bad:?}");
353	        }
354	        assert_eq!(parse_trusted_size(OsStr::from_bytes(b"9\xff")), None);
355	    }
356	
357	    #[test]
358	    fn trusted_root_accepts_exactly_64_lowercase_hex() {
359	        let h = hex(&roottrace::mth(&[b"a"]));
360	        let parsed = parse_trusted_root(OsStr::new(&h)).expect("valid root");
361	        assert_eq!(parsed, roottrace::mth(&[b"a"]));
362	        for bad in [
363	            "",
364	            &"a".repeat(63),
365	            &"a".repeat(65),
366	            // One uppercase digit.
367	            &{
368	                let mut s = h.clone();
369	                s.replace_range(0..1, "A");
370	                s
371	            },
372	            &format!("{h} "),
373	            &format!(" {h}"),
374	            &"z".repeat(64),
375	        ] {
376	            assert!(parse_trusted_root(OsStr::new(bad)).is_none(), "root {bad:?}");
377	        }
378	        assert!(parse_trusted_root(OsStr::from_bytes(&[b'a'; 65])).is_none());
379	    }
380	}
