488	/// Check a well-formed proof against the independently trusted tree size and
489	/// root, exactly per RFC 6962 section 2.1.1:
490	///
491	/// 1. the proof's `tree_size` must equal the trusted size (the proof must not
492	///    name its own trust anchor);
493	/// 2. the proof's `root` must equal the trusted root;
494	/// 3. `leaf_index` must exist in a tree of that size (already enforced while
495	///    parsing);
496	/// 4. starting from SHA-256(0x00 || record), the audit path hashes must
497	///    recombine in the order dictated by the (possibly uneven) tree geometry
498	///    into that root, consuming every supplied hash exactly once.
499	///
500	/// Duplicate content is never searched for: the check is against the exact
501	/// `leaf_index` the proof claims. A single-record tree needs an empty path;
502	/// a path that is too short or too long for the geometry cannot succeed.
503	fn verify_proof(proof: &Proof, record: &[u8], trusted_size: u64, trusted_root: &[u8; 32]) -> Result<(), String> {
504	    if proof.tree_size != trusted_size {
505	        return Err(format!(
506	            "proof tree_size {} does not match the trusted tree size {trusted_size}",
507	            proof.tree_size
508	        ));
509	    }
510	    if proof.root != *trusted_root {
511	        return Err("proof root does not match the trusted root".to_string());
512	    }
513	    let computed = include_record(
514	        leaf_hash(record),
515	        proof.leaf_index,
516	        proof.tree_size,
517	        &proof.audit_path,
518	    )
519	    .map_err(|e| e.to_string())?;
520	    if computed != *trusted_root {
521	        return Err("record bytes or audit_path do not match the root at the claimed position".to_string());
522	    }
523	    Ok(())
524	}
