575	/// Split raw bytes into records on LF (0x0a). The separator is not part of
576	/// any record. A trailing LF terminates the last record without adding an
577	/// empty one; an empty file yields zero records.
578	#[doc(hidden)]
579	pub fn split_records(data: &[u8]) -> Vec<&[u8]> {
580	    if data.is_empty() {
581	        return Vec::new();
582	    }
583	    let mut records: Vec<&[u8]> = data.split(|&b| b == b'\n').collect();
584	    if data.last() == Some(&b'\n') {
585	        records.pop();
586	    }
587	    records
588	}
