597	/// RFC 6962 section 2.1 leaf hash: SHA-256(0x00 || data). The prefix byte and
598	/// the record are fed to the hasher as two consecutive slices, so hashing a
599	/// record of any length needs no copy of the record and no allocation beyond
600	/// the hasher's fixed-size state.
601	fn leaf_hash(data: &[u8]) -> [u8; 32] {
602	    let mut h = new_leaf_hasher();
603	    h.update(data);
604	    h.finalize()
605	}
