607	/// RFC 6962 section 2.1 interior node hash: SHA-256(0x01 || left || right).
608	fn node_hash(left: &[u8; 32], right: &[u8; 32]) -> [u8; 32] {
609	    let mut h = Sha256::new();
610	    h.update(&[0x01]);
611	    h.update(left);
612	    h.update(right);
613	    h.finalize()
614	}
