687	/// RFC 6962 section 2.1 Merkle Tree Hash over SHA-256: the batch root, built
688	/// by the shared `build_tree` constructor so it follows exactly the same
689	/// rules as proof generation.
690	#[doc(hidden)]
691	pub fn mth(leaves: &[&[u8]]) -> [u8; 32] {
692	    build_tree(leaves, None, &mut Vec::new())
693	}
