883	/// Streaming SHA-256 (FIPS 180-4). The working state is the eight hash words
884	/// plus one 64-byte block buffer, so the temporary memory a hash needs is a
885	/// small constant no matter how long the hashed input is: a record is fed in
886	/// place from the batch buffer and is never copied for hashing.
887	struct Sha256 {
888	    h: [u32; 8],
889	    buf: [u8; 64],
890	    buf_len: usize,
891	    total_len: u64,
892	}
893	
894	impl Sha256 {
895	    fn new() -> Self {
896	        #[cfg(test)]
897	        SHA256_CALLS.with(|c| c.set(c.get() + 1));
898	        Sha256 {
899	            h: [
900	                0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c,
901	                0x1f83d9ab, 0x5be0cd19,
902	            ],
903	            buf: [0u8; 64],
904	            buf_len: 0,
905	            total_len: 0,
906	        }
907	    }
908	
909	    /// Feed the next chunk of input. Bytes are consumed straight from `data`;
910	    /// only a partial trailing block is ever staged in `buf`.
911	    fn update(&mut self, mut data: &[u8]) {
912	        self.total_len = self.total_len.wrapping_add(data.len() as u64);
913	        if self.buf_len > 0 {
914	            let take = (64 - self.buf_len).min(data.len());
915	            self.buf[self.buf_len..self.buf_len + take].copy_from_slice(&data[..take]);
916	            self.buf_len += take;
917	            data = &data[take..];
918	            if self.buf_len == 64 {
919	                let block = self.buf;
920	                self.compress(&block);
921	                self.buf_len = 0;
922	            }
923	        }
924	        while data.len() >= 64 {
925	            let (block, rest) = data.split_at(64);
926	            let mut staged = [0u8; 64];
927	            staged.copy_from_slice(block);
928	            self.compress(&staged);
929	            data = rest;
930	        }
931	        if !data.is_empty() {
932	            self.buf[..data.len()].copy_from_slice(data);
933	            self.buf_len = data.len();
934	        }
935	    }
936	
937	    /// Append the FIPS 180-4 padding (0x80, zeros, 64-bit big-endian bit
938	    /// length) inside the block buffer and produce the digest. At most one
939	    /// extra block is needed when the length field does not fit after the
940	    /// final data byte.
941	    fn finalize(mut self) -> [u8; 32] {
942	        let bit_len = self.total_len.wrapping_mul(8);
943	        self.update(&[0x80]);
944	        while self.buf_len != 56 {
945	            self.update(&[0]);
946	        }
947	        self.update(&bit_len.to_be_bytes());
948	        debug_assert_eq!(self.buf_len, 0, "padding must end on a block boundary");
949	
950	        let mut out = [0u8; 32];
951	        for (i, word) in self.h.iter().enumerate() {
952	            out[i * 4..i * 4 + 4].copy_from_slice(&word.to_be_bytes());
953	        }
954	        out
955	    }
956	
957	    /// The SHA-256 compression function over one 64-byte block.
958	    fn compress(&mut self, block: &[u8; 64]) {
959	        let mut w = [0u32; 64];
960	        for (i, word) in block.chunks_exact(4).enumerate() {
961	            w[i] = u32::from_be_bytes([word[0], word[1], word[2], word[3]]);
962	        }
963	        for i in 16..64 {
964	            let s0 = w[i - 15].rotate_right(7) ^ w[i - 15].rotate_right(18) ^ (w[i - 15] >> 3);
965	            let s1 = w[i - 2].rotate_right(17) ^ w[i - 2].rotate_right(19) ^ (w[i - 2] >> 10);
966	            w[i] = w[i - 16]
967	                .wrapping_add(s0)
968	                .wrapping_add(w[i - 7])
969	                .wrapping_add(s1);
970	        }
971	
972	        let [mut a, mut b, mut c, mut d, mut e, mut f, mut g, mut hh] = self.h;
973	        for i in 0..64 {
974	            let s1 = e.rotate_right(6) ^ e.rotate_right(11) ^ e.rotate_right(25);
975	            let ch = (e & f) ^ ((!e) & g);
976	            let t1 = hh
977	                .wrapping_add(s1)
978	                .wrapping_add(ch)
979	                .wrapping_add(K[i])
980	                .wrapping_add(w[i]);
981	            let s0 = a.rotate_right(2) ^ a.rotate_right(13) ^ a.rotate_right(22);
982	            let maj = (a & b) ^ (a & c) ^ (b & c);
983	            let t2 = s0.wrapping_add(maj);
984	            hh = g;
985	            g = f;
986	            f = e;
987	            e = d.wrapping_add(t1);
988	            d = c;
989	            c = b;
990	            b = a;
991	            a = t1.wrapping_add(t2);
992	        }
993	
994	        self.h[0] = self.h[0].wrapping_add(a);
995	        self.h[1] = self.h[1].wrapping_add(b);
996	        self.h[2] = self.h[2].wrapping_add(c);
997	        self.h[3] = self.h[3].wrapping_add(d);
998	        self.h[4] = self.h[4].wrapping_add(e);
999	        self.h[5] = self.h[5].wrapping_add(f);
1000	        self.h[6] = self.h[6].wrapping_add(g);
1001	        self.h[7] = self.h[7].wrapping_add(hh);
1002	    }
1003	}
