1280	                    // power-of-two batch every position sits at full depth.
1281	                    let depth = usize::BITS - (n - 1).leading_zeros();
1282	                    if n.is_power_of_two() {
1283	                        assert_eq!(path.len(), depth as usize, "n={n}, m={m}");
1284	                    } else {
1285	                        assert!(path.len() <= depth as usize, "n={n}, m={m}");
1286	                    }
1287	                }
1288	                let computed = rfc_recompute_root(refs[m], m, n, &path);
1289	                assert_eq!(hex_of(&computed), hex_of(&root), "proof mismatch at n={n}, m={m}");
1290	            }
1291	        }
1292	    }
