1600	                let (_, path) = root_and_path(&refs, m);
1601	                let bytes = proof_json(n as u64, m as u64, &root, &path).into_bytes();
1602	                let proof = parse_proof(&bytes).unwrap();
1603	                assert!(verify_proof(&proof, refs[m], n as u64, &other_root).is_err());
1604	            }
1605	        }
