1691	                assert_eq!(hex_of(&got), hex_of(&verify_proof_old(refs[m], m, n, &path)));
1692	                if !path.is_empty() {
1693	                    assert!(
1694	                        include_record(leaf_hash(refs[m]), m as u64, n as u64, &path[..path.len() - 1])
1695	                            .is_err()
1696	                    );
1697	                }
1698	                let mut longer = path.clone();
1699	                longer.push(leaf_hash(b"extra"));
1700	                assert!(include_record(leaf_hash(refs[m]), m as u64, n as u64, &longer).is_err());
1701	            }
1702	        }
1703	    }
1704	
1705	    /// The pre-existing test verifier (asserting form), reused above to cross
1706	    /// check the production verifier on common inputs.
1707	    fn verify_proof_old(leaf: &[u8], m: usize, n: usize, path: &[[u8; 32]]) -> [u8; 32] {
1708	        rfc_recompute_root(leaf, m, n, path)
1709	    }
1710	
1711	    // --- public library entry point ------------------------------------------
1712	
1713	    /// A real proof for `records[m]`, verified through the public API with
1714	    /// the batch root as the trusted root.
1715	    fn membership_of(records: &[&[u8]], m: usize, record: &[u8], trusted_size: u64, trusted_root: &[u8; 32]) -> Result<Membership, VerifyError> {
1716	        let (root, path) = root_and_path(records, m);
1717	        let size = records.len() as u64;
1718	        let bytes = proof_json(size, m as u64, &root, &path).into_bytes();
1719	        verify_membership(record, &bytes, trusted_size, trusted_root)
1720	    }
1721	
1722	    #[test]
1723	    fn api_success_returns_position_and_trusted_values() {
1724	        let records: Vec<&[u8]> = vec![b"alpha", b"beta", b"gamma", b"beta", b"delta"];
1725	        let root = mth(&records);
1726	        for (m, record) in records.iter().enumerate() {
1727	            let membership = membership_of(&records, m, record, 5, &root)
1728	                .unwrap_or_else(|e| panic!("position {m} must verify: {e}"));
1729	            // The claimed position is returned exactly, even for the duplicate
1730	            // "beta" at positions 1 and 3.
1731	            assert_eq!(membership.leaf_index(), m as u64);
1732	            // Size and root are the caller's trusted values, already checked
1733	            // against the proof — not fields read out of the proof.
1734	            assert_eq!(membership.tree_size(), 5);
1735	            assert_eq!(membership.root(), &root);
1736	        }
1737	    }
1738	
1739	    #[test]
1740	    fn api_zero_trusted_size_is_invalid_argument_not_empty_tree_membership() {
1741	        let records: Vec<&[u8]> = vec![b"only"];
1742	        let root = mth(&records);
1743	        let (_, path) = root_and_path(&records, 0);
1744	        let proof = proof_json(1, 0, &root, &path).into_bytes();
1745	        // A zero trusted size must be rejected as an invalid argument, never
1746	        // verified as "membership in the empty tree" and never reported as a
1747	        // cryptographic mismatch.
1748	        assert_eq!(
1749	            verify_membership(b"only", &proof, 0, &root),
1750	            Err(VerifyError::InvalidTrustedSize)
1751	        );
1752	        // Even a proof that itself claims tree_size 0 (malformed on its own)
1753	        // still hits the argument check first.
1754	        let zero_proof = format!(
1755	            "{{\"tree_size\":0,\"leaf_index\":0,\"root\":\"{}\",\"audit_path\":[]}}",
1756	            hex(&sha256(b""))
1757	        );
1758	        assert_eq!(
1759	            verify_membership(b"", zero_proof.as_bytes(), 0, &sha256(b"")),
1760	            Err(VerifyError::InvalidTrustedSize)
1761	        );
1762	    }
1763	
1764	    #[test]
1765	    fn api_distinguishes_malformed_proof_from_verification_failure() {
1766	        let records: Vec<&[u8]> = vec![b"a", b"b", b"c"];
1767	        let root = mth(&records);
1768	        let (_, path) = root_and_path(&records, 1);
1769	        let good = proof_json(3, 1, &root, &path).into_bytes();
1770	        assert!(verify_membership(b"b", &good, 3, &root).is_ok());
1771	
1772	        // Format problems → MalformedProof.
1773	        for bad in [
1774	            b"".as_slice(),
1775	            b"null",
1776	            b"{}",
1777	            &good[..good.len() - 2], // truncated
1778	            b"{\"tree_size\":3,\"leaf_index\":1,\"root\":\"00\",\"audit_path\":[]}",
1779	        ] {
1780	            assert!(
1781	                matches!(verify_membership(b"b", bad, 3, &root), Err(VerifyError::MalformedProof(_))),
1782	                "{bad:?} must be a malformed proof"
1783	            );
1784	        }
1785	
1786	        // Well-formed but not establishing inclusion → VerificationFailed.
1787	        let mut wrong_root = root;
1788	        wrong_root[0] ^= 0x01;
1789	        let short_path = proof_json(3, 1, &root, &path[..path.len() - 1]).into_bytes();
1790	        assert!(matches!(
1791	            verify_membership(b"b", &good, 4, &root),
1792	            Err(VerifyError::VerificationFailed(_))
1793	        ));
1794	        assert!(matches!(
1795	            verify_membership(b"b", &good, 3, &wrong_root),
1796	            Err(VerifyError::VerificationFailed(_))
1797	        ));
1798	        assert!(matches!(
1799	            verify_membership(b"x", &good, 3, &root),
1800	            Err(VerifyError::VerificationFailed(_))
1801	        ));
1802	        assert!(matches!(
1803	            verify_membership(b"b", &short_path, 3, &root),
1804	            Err(VerifyError::VerificationFailed(_))
1805	        ));
1806	    }
1807	
1808	    #[test]
1809	    fn api_failure_never_yields_a_membership() {
1810	        // No failing call may return anything shaped like a success: every
1811	        // error path above is an Err, and Membership can only be constructed
1812	        // by a successful verification (its fields are private).
1813	        let records: Vec<&[u8]> = vec![b"a", b"b"];
1814	        let root = mth(&records);
1815	        let (_, path) = root_and_path(&records, 0);
1816	        let proof = proof_json(2, 0, &root, &path).into_bytes();
1817	        assert!(verify_membership(b"a", &proof, 2, &root).is_ok());
1818	        assert!(verify_membership(b"a", &proof, 0, &root).is_err());
1819	        assert!(verify_membership(b"a", b"garbage", 2, &root).is_err());
1820	        assert!(verify_membership(b"b", &proof, 2, &root).is_err());
1821	    }
1822	
1823	    #[test]
1824	    fn api_record_bytes_are_verbatim_including_empty_and_non_utf8() {
1825	        // An empty byte slice is one empty record.
1826	        let records: Vec<&[u8]> = vec![b"", b"x"];
1827	        let root = mth(&records);
1828	        assert!(membership_of(&records, 0, b"", 2, &root).is_ok());
1829	        // Trailing LF / CR / space / NUL all belong to the record.
1830	        for suffix in [b"\n".as_slice(), b"\r", b" ", b"\x00"] {
1831	            assert!(
1832	                membership_of(&records, 0, suffix, 2, &root).is_err(),
1833	                "suffix {suffix:?} must change the record"
1834	            );
1835	        }
1836	        // Non-UTF-8 bytes take part as they are.
1837	        let bin: &[u8] = b"\xff\xfe\x00bin";
1838	        let records: Vec<&[u8]> = vec![b"a", bin];
1839	        let root = mth(&records);
1840	        assert!(membership_of(&records, 1, bin, 2, &root).is_ok());
1841	    }
1842	
1843	    #[test]
1844	    fn api_accepts_reordered_whitespace_and_escaped_proofs() {
1845	        let records: Vec<&[u8]> = vec![b"a", b"b"];
1846	        let root = mth(&records);
1847	        let (_, path) = root_and_path(&records, 1);
1848	        let h = hex(&root);
1849	        let p0 = hex(&path[0]);
1850	        // Reordered fields, arbitrary whitespace, and \uXXXX-escaped key and
1851	        // hash characters all keep the existing acceptance rules.
1852	        let pretty = format!(
1853	            " {{\n \"audit_path\" : [ \"{p0}\" ] ,\n \"root\" : \"{h}\" ,\n \"leaf_index\" : 1 ,\n \"tree_size\" : 2 }} \n"
1854	        );
1855	        let m = verify_membership(b"b", pretty.as_bytes(), 2, &root).expect("pretty proof");
1856	        assert_eq!(m.leaf_index(), 1);
1857	        let escaped = format!(
1858	            "{{\"tree_siz\\u0065\":2,\"leaf_index\":1,\"root\":\"{h}\",\"audit_path\":[\"{p0}\"]}}"
1859	        );
1860	        assert!(verify_membership(b"b", escaped.as_bytes(), 2, &root).is_ok());
1861	        // Duplicate fields (even via escapes) stay rejected as malformed.
1862	        let dup = format!(
1863	            "{{\"tree_size\":2,\"tree_siz\\u0065\":2,\"leaf_index\":1,\"root\":\"{h}\",\"audit_path\":[\"{p0}\"]}}"
1864	        );
1865	        assert!(matches!(
1866	            verify_membership(b"b", dup.as_bytes(), 2, &root),
1867	            Err(VerifyError::MalformedProof(_))
1868	        ));
1869	    }
1870	
1871	    #[test]
1872	    fn api_keeps_full_64bit_meaning_of_size_and_index() {
1873	        // A synthetic proof for a tree of 2^63 records at index 2^32: the
1874	        // audit path element i is the 64-char lowercase hex of i, and the
1875	        // trusted root is recomputed here with the internal verifier. The
1876	        // point is that u64 sizes/indices flow through verify_membership
1877	        // untruncated and come back in the Membership result unchanged.
1878	        let record = b"big-tree-record\x00\xff\xfe";
1879	        let size: u64 = 1 << 63;
1880	        let index: u64 = 1 << 32;
1881	        let path: Vec<[u8; 32]> = (0..63u64)
1882	            .map(|i| {
1883	                let s = format!("{i:064x}");
1884	                let mut h = [0u8; 32];
1885	                for (j, pair) in s.as_bytes().chunks_exact(2).enumerate() {
1886	                    h[j] = (hex_nibble(pair[0]).unwrap() << 4) | hex_nibble(pair[1]).unwrap();
1887	                }
1888	                h
1889	            })
1890	            .collect();
1891	        let root = include_record(leaf_hash(record), index, size, &path).unwrap();
1892	        let proof = proof_json(size, index, &root, &path).into_bytes();
1893	        let m = verify_membership(record, &proof, size, &root).expect("2^63 tree must verify");
1894	        assert_eq!(m.leaf_index(), 1u64 << 32);
1895	        assert_eq!(m.tree_size(), 1u64 << 63);
1896	        assert_eq!(m.root(), &root);
1897	        // Off by one in the trusted size or the claimed index must fail, not
1898	        // truncate to a smaller tree.
1899	        assert!(matches!(
1900	            verify_membership(record, &proof, size - 1, &root),
1901	            Err(VerifyError::VerificationFailed(_))
1902	        ));
1903	        let off = proof_json(size, index + 1, &root, &path).into_bytes();
1904	        assert!(matches!(
1905	            verify_membership(record, &off, size, &root),
1906	            Err(VerifyError::VerificationFailed(_))
1907	        ));
1908	    }
1909	}
