        let cases = [
            format!("{{\"tree_size\":\"2\",\"leaf_index\":0,\"root\":\"{h}\",\"audit_path\":[\"{p0}\"]}}"),
            format!("{{\"tree_size\":2.0,\"leaf_index\":0,\"root\":\"{h}\",\"audit_path\":[\"{p0}\"]}}"),
            format!("{{\"tree_size\":2,\"leaf_index\":true,\"root\":\"{h}\",\"audit_path\":[\"{p0}\"]}}"),
