294	
295	    let missing_rec = dir.child(b"no-record-\xff.bin");
296	    for args in [
297	        vec![
298	            b"verify".as_slice(),
299	            missing_rec.as_os_str().as_bytes(),
300	            proof.as_os_str().as_bytes(),
301	            b"3",
302	            trusted_root.as_bytes(),
303	        ],
304	    ] {
305	        let out = run(&args, None);
306	        assert_eq!(out.status.code(), Some(1));
307	        assert!(out.stdout.is_empty());
308	        assert!(!out.stderr.is_empty());
309	    }
310	
311	    let sub = dir.child(b"dir-\xff");
312	    fs::create_dir(&sub).unwrap();
313	    let out = run(
314	        &[
315	            b"verify",
316	            sub.as_os_str().as_bytes(),
317	            proof.as_os_str().as_bytes(),
318	            b"3",
319	            trusted_root.as_bytes(),
320	        ],
321	        None,
322	    );
323	    assert_eq!(out.status.code(), Some(1));
324	    assert!(out.stdout.is_empty());
325	    assert!(!out.stderr.is_empty());
326	
327	    // A directory in the proof path position likewise fails at read time.
328	    let out = run(
329	        &[
330	            b"verify",
331	            record.as_os_str().as_bytes(),
332	            sub.as_os_str().as_bytes(),
333	            b"3",
334	            trusted_root.as_bytes(),
335	        ],
336	        None,
337	    );
338	    assert_eq!(out.status.code(), Some(1));
339	    assert!(out.stdout.is_empty());
340	    assert!(!out.stderr.is_empty());
341	}
