343	/// Non-UTF-8 bytes in the command name or in the trusted size/root arguments
344	/// are syntax errors: exit 2 with the usage text and nothing on stdout.
345	#[test]
346	fn non_utf8_verify_arguments_are_usage_errors() {
347	    let dir = TempDir::create();
348	    let record = dir.write(b"record-\xff.bin", b"alpha\r");
349	    let proof = dir.write(b"proof-\xff.json", b"{}");
350	    let rec_bytes = record.as_os_str().as_bytes();
351	    let prf_bytes = proof.as_os_str().as_bytes();
352	
353	    let bad_cmd = run(&[b"ver\xffy", rec_bytes, prf_bytes, b"3", b"a"], None);
354	    assert_eq!(bad_cmd.status.code(), Some(2));
355	    assert!(bad_cmd.stdout.is_empty());
356	    assert!(String::from_utf8_lossy(&bad_cmd.stderr).contains("Usage"));
357	
358	    for bad_size in [b"3\xff".as_slice(), b"\xff"] {
359	        let out = run(&[b"verify", rec_bytes, prf_bytes, bad_size, b"a"], None);
360	        assert_eq!(out.status.code(), Some(2), "size {bad_size:?}");
361	        assert!(out.stdout.is_empty());
362	        assert!(String::from_utf8_lossy(&out.stderr).contains("Usage"));
363	    }
