366	    let mut bad_root = vec![b'a'; 64];
367	    bad_root[0] = 0xff;
368	    let out = run(&[b"verify", rec_bytes, prf_bytes, b"3", &bad_root], None);
369	    assert_eq!(out.status.code(), Some(2));
370	    assert!(out.stdout.is_empty());
371	    assert!(String::from_utf8_lossy(&out.stderr).contains("Usage"));
