383	    assert_eq!(bad_cmd.status.code(), Some(2));
384	    assert!(bad_cmd.stdout.is_empty());
385	    assert!(String::from_utf8_lossy(&bad_cmd.stderr).contains("Usage"));
386	
387	    for bad_index in [b"1\xff".as_slice(), b"\xff".as_slice()] {
388	        let out = run(&[b"prove", file_bytes, bad_index], None);
389	        assert_eq!(out.status.code(), Some(2), "index {bad_index:?}");
390	        assert!(out.stdout.is_empty(), "index {bad_index:?}");
391	        assert!(
392	            String::from_utf8_lossy(&out.stderr).contains("Usage"),
393	            "index {bad_index:?}"
394	        );
395	    }
396	}
